WITH scored AS (SELECT id, browser, started_at, FIRST_VALUE(country) IGNORE NULLS OVER (PARTITION BY country ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY country, browser ORDER BY started_at ASC, id ASC) AS seq_no, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at DESC, id ASC) AS row_seq FROM sessions) SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, seq_no, CASE WHEN seq_no >= 7 THEN 'HIGH' ELSE 'LOW' END AS seq_no_tier, MAX(started_at) AS last_started_at, MAX(started_at) AS last_started_at_2, MAX(started_at) AS last_seen FROM scored GROUP BY DATE_TRUNC('MONTH', started_at), seq_no, CASE WHEN seq_no >= 7 THEN 'HIGH' ELSE 'LOW' END
